import * as React from "react";

export function RadarSweepTactical({ className = "w-full h-full min-h-[260px]" }: { className?: string }): React.JSX.Element {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  React.useEffect(() => {
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d")!;
    let w = (canvas.width = canvas.parentElement?.clientWidth ?? 600);
    let h = (canvas.height = canvas.parentElement?.clientHeight ?? 300);
    const cx = w / 2, cy = h / 2;
    const R = Math.min(w, h) * 0.42;
    let angle = 0;
    const blips = Array.from({ length: 8 }, () => ({ r: Math.random() * R * 0.9, a: Math.random() * Math.PI * 2, life: 0 }));
    let animId: number;
    const draw = () => {
      ctx.fillStyle = "rgba(0, 10, 5, 0.3)";
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = "rgba(0, 255, 100, 0.15)";
      for (let i = 1; i <= 4; i++) { ctx.beginPath(); ctx.arc(cx, cy, R * i / 4, 0, Math.PI * 2); ctx.stroke(); }
      ctx.beginPath(); ctx.moveTo(cx - R, cy); ctx.lineTo(cx + R, cy); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(cx, cy - R); ctx.lineTo(cx, cy + R); ctx.stroke();
      const grad = ctx.createConicalGradient ? undefined : null;
      ctx.fillStyle = "rgba(0, 255, 80, 0.04)";
      ctx.beginPath(); ctx.moveTo(cx, cy); ctx.arc(cx, cy, R, angle - 0.6, angle); ctx.closePath(); ctx.fill();
      ctx.strokeStyle = "rgba(0, 255, 80, 0.9)";
      ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(cx, cy);
      ctx.lineTo(cx + Math.cos(angle) * R, cy + Math.sin(angle) * R);
      ctx.stroke();
      for (const b of blips) {
        const angleDiff = ((angle - b.a) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2);
        if (angleDiff < 0.15) b.life = 1;
        b.life *= 0.985;
        if (b.life > 0.05) {
          const bx = cx + Math.cos(b.a) * b.r, by = cy + Math.sin(b.a) * b.r;
          ctx.fillStyle = `rgba(0, 255, 80, ${b.life})`;
          ctx.beginPath(); ctx.arc(bx, by, 3, 0, Math.PI * 2); ctx.fill();
        }
      }
      angle = (angle + 0.025) % (Math.PI * 2);
      animId = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(animId);
  }, []);
  return <div className={className}><canvas ref={canvasRef} className="w-full h-full block" /></div>;
}

import * as React from "react";
import { RadarSweepTactical } from "./radar-sweep-tactical";

export default function RadarSweepTacticalDemo(): React.JSX.Element {
  return (
    <div className="relative flex min-h-[480px] w-full overflow-hidden rounded-2xl bg-neutral-950 border border-neutral-800">
      {/* Background canvas layer */}
      <RadarSweepTactical className="absolute inset-0 h-full w-full" />

      {/* Foreground content layer */}
      <div className="relative z-10 flex h-full w-full flex-col items-center justify-center p-8 text-center my-auto">
        <span className="rounded-full border border-white/15 bg-white/10 px-3.5 py-1 text-xs font-mono font-medium text-neutral-300 backdrop-blur-md">
          Ambient Canvas Engine
        </span>
        <h2 className="mt-4 text-3xl sm:text-5xl font-bold tracking-tight text-white">
          Radar Sweep Tactical
        </h2>
        <p className="mt-3 max-w-md text-sm sm:text-base text-neutral-400">
          Hardware-accelerated ambient visuals that react seamlessly to viewport and pointer interactions.
        </p>
      </div>
    </div>
  );
}
